      if (!this.time.consumeExpiration(timer)) continue
      const entity = this.worldHost.state.world.entities.find(/* 比较 candidate.uuid 与 timer.entityUuid，返回严格相等的判断结果。 */ candidate => candidate.uuid === timer.entityUuid)
