    const primary = this.scriptServices.resolveAsset(entity.script2D?.scriptAsset)?.uuid
    const dispatched = new Set<string>([...alreadyDispatched, ...(canonicalCallback && primary ? [JSON.stringify([primary, canonicalCallback])] : [])])
