    try { this.runEntityFunction(entity, 'on_destroy', undefined, undefined, true, undefined, true); this.runEventSheetHandlers(entity, 'destroy', '', 'on_destroy') }
    finally { this.callbackWorld = previous; this.invalidateScriptWorld() }
  }

