  /** 结构说明（自动提取）：inspectObjectRuntime；输入 entityUuid；直接调用 this.worldHost.state.world.entities.find、authoredEntities.get、resolveAsset、Set、filter 等；包含循环处理。 */ inspectObjectRuntime(entityUuid: string) {
