    .flatMap(/* 从有效相机实体生成经过跟随、混合和视口校正的渲染视图。 */ entity => {
      const component = entity.camera2D
      if (!entity.enabled || !component?.enabled || component.removed || !component.active) return []
      const transform = worldTransform(entity, entities)
