/* 根据缩放调整网格间距，在数量上限内提交固定屏幕线宽的编辑网格。 */
function submitEditorGrid(renderer: Renderer2D, options: SceneRenderOptions): void {
  const camera = options.editorCamera
  const scale = Math.max(.000001, camera.scale)
